set -e
cd "$(dirname "$0")"
mkdir -p site quiet h3site
printf '%s\n' 'hello from surl' > site/hello.txt
printf '%s\n' 'hello from surl' > quiet/hello.txt
printf '%s\n' 'hello from surl' > h3site/hello.txt
openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"
surl --directory site --cert server.pem --key server.key https://127.0.0.1:8080/ &
sleep 1
curl --http3 --cacert server.pem -w "HTTP/%{http_version}\n" https://127.0.0.1:8080/hello.txt
kill $(jobs -p)
